@startuml

class SensorController {
  + systemName : string
}

class Apartment {
  + address : string
}

class Inhabitant {
  + username : string
  + password : string
}

class Room {
  + description : string
}

abstract class Sensor {
  + vendorId : string
  + description : string
  + unit : Unit
}

class TemperatureSensor {
  + minValue : double
  + maxValue : double
}

class PowerSensor {
  + totalPowerConsumption : double
}

class SensorValue {
  + timestamp : datetime
  + value : double
}

enum Unit {
  CELSIUS
  WATT
}

class EMonitor {
  + systemName : string
}

class AlertMessage {
  + content : string
}

class SensorController "1" *-- "1" Apartment
Apartment "1" *-- "2..*" Room
Room "1" *-- "1..*" Sensor
Inhabitant "*" -- "1" SensorController
Inhabitant "1" -- "0..*" Sensor
Inhabitant "1" -- "0..*" Room
Sensor "1" *-- "0..*" SensorValue
Sensor "1" -- "0..1" lastValue : SensorValue
SensorController "1" -- "0..1" EMonitor
EMonitor "1" -- "*" Sensor
EMonitor "1" -- "0..1" AlertMessage
Apartment "1" -- "0..1" emailAddress : string
SensorController "1" -- "0..1" emailAddress : string

TemperatureSensor --|> Sensor
PowerSensor --|> Sensor

@enduml

